// 필수 필드 확인 + 값 정리 (이메일은 소문자·공백 제거)
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const str = v => String(v ?? '').trim();

return $input.all().map(({ json }) => {
  const b = json.body ?? {};
  const lead = {
    company_name: str(b.company_name),
    industry: str(b.industry),
    employees: Number(b.employees) || null,
    region: str(b.region),
    contact_name: str(b.contact_name),
    contact_role: str(b.contact_role),
    contact_email: str(b.contact_email).toLowerCase(),
    channel: str(b.channel),
  };
  const errors = [];
  if (!lead.company_name) errors.push('company_name 누락');
  if (!lead.contact_email) errors.push('contact_email 누락');
  else if (!EMAIL.test(lead.contact_email)) errors.push('contact_email 형식 오류');
  return { json: { valid: errors.length === 0, errors, lead, received_at: new Date().toISOString() } };
});

// 기업은 정규화한 회사명, 연락처는 이메일 기준으로 중복 확인 후 저장
// ponytail: 워크플로 static data를 저장소로 사용. 실제 운영 시 CRM/DB 노드로 교체
const db = $getWorkflowStaticData('global');
db.companies ??= {};
db.contacts ??= {};
const companyKey = name => name.replace(/\(주\)|주식회사|\s/g, '').toLowerCase();
const filled = obj => Object.fromEntries(Object.entries(obj).filter(([, v]) => v !== '' && v !== null));

return $input.all().map(({ json: { lead } }) => {
  const now = new Date().toISOString();
  const key = companyKey(lead.company_name);
  const { contact_name, contact_role, contact_email, channel, ...companyFields } = lead;

  if (!db.companies[key]) {
    const id = 'C' + String(Object.keys(db.companies).length + 1).padStart(3, '0');
    db.companies[key] = { company_id: id, created_at: now };
  }
  const company = Object.assign(db.companies[key], filled(companyFields), { updated_at: now });

  const existing = db.contacts[contact_email];
  const contact = {
    status: 'researched',
    created_at: now,
    ...existing,
    ...filled({ contact_name, contact_role, contact_email, channel }),
    company_id: company.company_id,
    updated_at: now,
  };
  db.contacts[contact_email] = contact;

  const action = existing ? 'updated' : 'created';
  const next_action = existing ? '기존 리드 이력 확인' : '담당자 배정 및 첫 연락';
  return { json: { action, company, contact, next_action } };
});

// 검증 실패 입력을 오류 로그에 기록 (최근 100건 유지)
const db = $getWorkflowStaticData('global');
db.errors ??= [];
return $input.all().map(({ json }) => {
  const entry = { at: json.received_at, errors: json.errors, input: json.lead };
  db.errors.push(entry);
  if (db.errors.length > 100) db.errors.splice(0, db.errors.length - 100);
  return { json: entry };
});
